export function defaultTrendsDateRange() {
  const end = new Date();
  const start = new Date();
  start.setDate(start.getDate() - 30);
  return {
    start_date: start.toISOString().slice(0, 10),
    end_date: end.toISOString().slice(0, 10),
  };
}

export const emptyTrendsShape = {
  summary: {
    ticket_count: 0,
    resolved_count: 0,
    avg_resolution_hours: null,
    median_resolution_hours: null,
    breached_sla_count: 0,
  },
  by_department: [],
  by_day: [],
  by_status: [],
  tickets: [],
};

export function resolvedLike(status) {
  const s = String(status || "").toLowerCase();
  return s === "resolved" || s === "closed";
}

export function formatResolutionHours(hours) {
  if (hours == null || Number.isNaN(hours)) return "—";
  if (hours < 1) return `${Math.round(hours * 60)} mins`;
  if (hours < 24) return `${hours.toFixed(1)} hrs`;
  return `${(hours / 24).toFixed(1)} days`;
}

export function parseTrendsResponse(response) {
  const raw = response?.data ?? response;
  if (!raw || typeof raw !== "object") return { ...emptyTrendsShape };

  const summary = raw.summary ||
    raw.metrics || {
      ticket_count: raw.ticket_count ?? raw.total_tickets,
      resolved_count: raw.resolved_count,
      avg_resolution_hours:
        raw.avg_resolution_hours ?? raw.average_resolution_hours,
      median_resolution_hours: raw.median_resolution_hours,
      breached_sla_count: raw.breached_sla_count ?? raw.sla_breached_count,
    };

  return {
    summary: {
      ticket_count: summary.ticket_count ?? 0,
      resolved_count: summary.resolved_count ?? 0,
      avg_resolution_hours: summary.avg_resolution_hours ?? null,
      median_resolution_hours: summary.median_resolution_hours ?? null,
      breached_sla_count: summary.breached_sla_count ?? 0,
    },
    by_department: raw.by_department || raw.department_breakdown || [],
    by_day: raw.by_day || raw.daily || raw.chart_data || [],
    by_status: raw.by_status || raw.status_breakdown || [],
    tickets: raw.tickets || raw.ticket_list || [],
  };
}

function ticketResolutionHours(ticket) {
  if (ticket.resolution_hours != null) return Number(ticket.resolution_hours);
  if (ticket.resolution_time_hours != null)
    return Number(ticket.resolution_time_hours);
  if (!ticket.created_at || !ticket.updated_at) return null;
  const created = new Date(ticket.created_at).getTime();
  const updated = new Date(ticket.updated_at).getTime();
  if (Number.isNaN(created) || Number.isNaN(updated) || updated <= created)
    return null;
  return (updated - created) / (1000 * 60 * 60);
}

function slaBreached(ticket) {
  if (ticket.sla_breached != null) return Boolean(ticket.sla_breached);
  if (ticket.breached_sla != null) return Boolean(ticket.breached_sla);
  if (ticket.is_overdue != null) return Boolean(ticket.is_overdue);
  return false;
}

export function aggregateTicketsForTrends(tickets, filters = {}) {
  let list = Array.isArray(tickets) ? [...tickets] : [];

  if (filters.start_date) {
    const start = new Date(filters.start_date).getTime();
    list = list.filter((t) => new Date(t.created_at).getTime() >= start);
  }
  if (filters.end_date) {
    const end = new Date(`${filters.end_date}T23:59:59`).getTime();
    list = list.filter((t) => new Date(t.created_at).getTime() <= end);
  }
  if (filters.location_id) {
    list = list.filter(
      (t) => String(t.location_id) === String(filters.location_id),
    );
  }
  if (filters.department_id) {
    list = list.filter(
      (t) => String(t.department_id) === String(filters.department_id),
    );
  }
  if (filters.status) {
    list = list.filter((t) => t.status === filters.status);
  }
  if (filters.sla_compliance === "met") {
    list = list.filter((t) => !slaBreached(t));
  }
  if (filters.sla_compliance === "breached") {
    list = list.filter((t) => slaBreached(t));
  }

  const resolutionHours = list
    .map(ticketResolutionHours)
    .filter((h) => h != null && !Number.isNaN(h));

  const avg =
    resolutionHours.length > 0
      ? resolutionHours.reduce((a, b) => a + b, 0) / resolutionHours.length
      : null;

  const sorted = [...resolutionHours].sort((a, b) => a - b);
  const median =
    sorted.length > 0
      ? sorted.length % 2 === 0
        ? (sorted[sorted.length / 2 - 1] + sorted[sorted.length / 2]) / 2
        : sorted[Math.floor(sorted.length / 2)]
      : null;

  const deptMap = new Map();
  list.forEach((t) => {
    const name =
      t.department?.name ||
      t.department_name ||
      `Department ${t.department_id || "—"}`;
    const hours = ticketResolutionHours(t);
    const entry = deptMap.get(name) || { count: 0, resolutionSum: 0, n: 0 };
    entry.count += 1;
    if (hours != null) {
      entry.resolutionSum += hours;
      entry.n += 1;
    }
    deptMap.set(name, entry);
  });

  const by_department = [...deptMap.entries()].map(([department_name, v]) => ({
    department_name,
    count: v.count,
    avg_resolution_hours: v.n ? v.resolutionSum / v.n : null,
  }));

  const dayMap = new Map();
  list.forEach((t) => {
    if (!t.created_at) return;
    const day = String(t.created_at).slice(0, 10);
    dayMap.set(day, (dayMap.get(day) || 0) + 1);
  });
  const by_day = [...dayMap.entries()]
    .map(([date, count]) => ({ date, count, label: date }))
    .sort((a, b) => a.date.localeCompare(b.date));

  const statusMap = new Map();
  list.forEach((t) => {
    const status = t.status || "Unknown";
    statusMap.set(status, (statusMap.get(status) || 0) + 1);
  });
  const by_status = [...statusMap.entries()].map(([status, count]) => ({
    status,
    count,
  }));

  return {
    summary: {
      ticket_count: list.length,
      resolved_count: list.filter((t) => resolvedLike(t.status)).length,
      avg_resolution_hours: avg,
      median_resolution_hours: median,
      breached_sla_count: list.filter(slaBreached).length,
    },
    by_department,
    by_day,
    by_status,
    tickets: list.slice(0, 50),
  };
}

export function buildTrendsQueryParams(filters) {
  const params = {};
  if (filters.location_id) params.location_id = filters.location_id;
  if (filters.department_id) params.department_id = filters.department_id;
  if (filters.sla_id) params.sla_id = filters.sla_id;
  if (filters.sla_compliance) params.sla_compliance = filters.sla_compliance;
  if (filters.status) params.status = filters.status;
  if (filters.start_date) params.start_date = filters.start_date;
  if (filters.end_date) params.end_date = filters.end_date;
  return params;
}
