import React, { useState, useEffect, useCallback } from "react";
import {
  Box,
  Typography,
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  TextField,
  Button,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Card,
  CardContent,
  CircularProgress,
  Alert,
  Chip,
} from "@mui/material";
import { TrendingUp, Circle } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";
import { apiRequest } from "../utils/apiRequest";
import { API } from "../api/endpoints";
import { FILTER_TICKET_STATUSES } from "../utils/ticketStatuses";
import {
  aggregateTicketsForTrends,
  buildTrendsQueryParams,
  defaultTrendsDateRange,
  emptyTrendsShape,
  formatResolutionHours,
  parseTrendsResponse,
} from "../utils/trendsAnalysis";

const STATUS_OPTIONS = FILTER_TICKET_STATUSES;

function SummaryCard({ label, value, color }) {
  return (
    <Card
      sx={{
        backgroundColor: color,
        color: "#fff",
        textAlign: "center",
        height: "100%",
        borderRadius: 2,
      }}
    >
      <CardContent>
        <Typography variant="h4" sx={{ fontWeight: "bold" }}>
          {value}
        </Typography>
        <Typography variant="body2">{label}</Typography>
      </CardContent>
    </Card>
  );
}

function DayVolumeChart({ byDay }) {
  const data = Array.isArray(byDay) ? byDay : [];
  const max = Math.max(...data.map((d) => d.count || 0), 1);

  if (!data.length) {
    return (
      <Typography color="text.secondary" sx={{ py: 2, textAlign: "center" }}>
        No volume data for the selected range
      </Typography>
    );
  }

  return (
    <Box
      sx={{
        display: "flex",
        alignItems: "flex-end",
        gap: 0.5,
        height: 160,
        px: 1,
        overflowX: "auto",
      }}
    >
      {data.map((point) => {
        const count = point.count || 0;
        const heightPct = `${Math.max((count / max) * 100, 4)}%`;
        return (
          <Box
            key={point.date || point.label}
            sx={{
              flex: "1 0 28px",
              minWidth: 28,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 0.5,
            }}
          >
            <Typography variant="caption" sx={{ fontSize: "0.65rem" }}>
              {count}
            </Typography>
            <Box
              sx={{
                width: "100%",
                height: heightPct,
                minHeight: 4,
                bgcolor: "#F97316",
                borderRadius: "4px 4px 0 0",
              }}
              title={`${point.label || point.date}: ${count} tickets`}
            />
            <Typography
              variant="caption"
              sx={{
                fontSize: "0.6rem",
                transform: "rotate(-45deg)",
                whiteSpace: "nowrap",
                mt: 1,
              }}
            >
              {(point.label || point.date || "").slice(5)}
            </Typography>
          </Box>
        );
      })}
    </Box>
  );
}

const TrendsAnalysisTab = ({
  locations = [],
  departments = [],
  baseApiPath,
}) => {
  const navigate = useNavigate();
  const [filters, setFilters] = useState(() => ({
    location_id: "",
    department_id: "",
    sla_id: "",
    sla_compliance: "",
    status: "",
    ...defaultTrendsDateRange(),
  }));
  const [trendsData, setTrendsData] = useState(emptyTrendsShape);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [usedFallback, setUsedFallback] = useState(false);
  const [slaOptions, setSlaOptions] = useState([]);

  const getPriorityColor = (priority) => {
    switch (priority) {
      case "High":
        return "#f44336";
      case "Medium":
        return "#ff9800";
      case "Low":
        return "#4caf50";
      case "Urgent":
        return "#d32f2f";
      default:
        return "#666";
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case "In Progress":
        return "#ff9800";
      case "Resolved":
      case "Closed":
        return "#4caf50";
      case "Pending Confirmation":
        return "#546e7a";
      case "Waiting for Parts":
        return "#ed6c02";
      default:
        return "#666";
    }
  };

  const fetchSlaOptions = useCallback(async () => {
    try {
      const res = await apiRequest({ ...API.slaList });
      const list = res?.data ?? res;
      setSlaOptions(Array.isArray(list) ? list : []);
    } catch {
      setSlaOptions([]);
    }
  }, []);

  const fetchTrends = useCallback(async () => {
    setLoading(true);
    setError("");
    setUsedFallback(false);

    const params = buildTrendsQueryParams(filters);

    try {
      const response = await apiRequest({
        method: "GET",
        url: `${baseApiPath}tickets/trend`,
        params,
      });
      setTrendsData(parseTrendsResponse(response));
    } catch (apiError) {
      try {
        const listRes = await apiRequest({
          method: "GET",
          url: `${baseApiPath}ticket/list`,
          params: { paginate: false, per_page: 500, ...params },
        });
        const ticketList =
          listRes?.data?.data || listRes?.data || listRes?.tickets || [];
        setTrendsData(aggregateTicketsForTrends(ticketList, filters));
        setUsedFallback(true);
      } catch (fallbackError) {
        setTrendsData(emptyTrendsShape);
        setError(
          fallbackError?.message ||
            apiError?.message ||
            "Failed to load trends data",
        );
      }
    } finally {
      setLoading(false);
    }
  }, [filters, baseApiPath]);

  useEffect(() => {
    fetchSlaOptions();
  }, [fetchSlaOptions]);

  useEffect(() => {
    fetchTrends();
  }, []);

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters((prev) => {
      const next = { ...prev, [name]: value };
      if (name === "sla_id" && value) next.sla_compliance = "";
      if (name === "sla_compliance" && value) next.sla_id = "";
      return next;
    });
  };

  const handleReset = () => {
    setFilters({
      location_id: "",
      department_id: "",
      sla_id: "",
      sla_compliance: "",
      status: "",
      ...defaultTrendsDateRange(),
    });
  };

  const { summary } = trendsData;

  return (
    <Box sx={{ maxWidth: 1400, mx: "auto" }}>
      <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 1 }}>
        <TrendingUp sx={{ color: "#F97316" }} />
        <Typography variant="h5" sx={{ fontWeight: "bold" }}>
          Trends Analysis
        </Typography>
      </Box>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Aggregated ticket performance and resolution metrics. Filters apply to
        ticket <strong>creation date</strong>.
      </Typography>

      <Paper variant="outlined" sx={{ p: 2, mb: 3 }}>
        <Grid container spacing={2}>
          <Grid size={{ xs: 12, sm: 6, md: 4 }}>
            <FormControl fullWidth size="small">
              <InputLabel>Outlet</InputLabel>
              <Select
                name="location_id"
                value={filters.location_id}
                label="Outlet"
                onChange={handleFilterChange}
              >
                <MenuItem value="">All Outlets</MenuItem>
                {locations.map((loc) => (
                  <MenuItem key={loc.id} value={loc.id}>
                    {loc.name}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid size={{ xs: 12, sm: 6, md: 4 }}>
            <FormControl fullWidth size="small">
              <InputLabel>Department</InputLabel>
              <Select
                name="department_id"
                value={filters.department_id}
                label="Department"
                onChange={handleFilterChange}
              >
                <MenuItem value="">All Departments</MenuItem>
                {departments.map((dept) => (
                  <MenuItem key={dept.id} value={dept.id}>
                    {dept.name}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid size={{ xs: 12, sm: 6, md: 4 }}>
            <FormControl fullWidth size="small">
              <InputLabel>SLA</InputLabel>
              <Select
                name={slaOptions.length ? "sla_id" : "sla_compliance"}
                value={filters.sla_id || filters.sla_compliance || ""}
                label="SLA"
                onChange={(e) => {
                  if (slaOptions.length) {
                    handleFilterChange({
                      target: { name: "sla_id", value: e.target.value },
                    });
                  } else {
                    handleFilterChange({
                      target: {
                        name: "sla_compliance",
                        value: e.target.value,
                      },
                    });
                  }
                }}
              >
                <MenuItem value="">All SLA</MenuItem>
                {slaOptions.length
                  ? slaOptions.map((sla) => (
                      <MenuItem key={sla.id} value={sla.id}>
                        {sla.name || sla.department?.name || `SLA #${sla.id}`}
                      </MenuItem>
                    ))
                  : [
                      <MenuItem key="met" value="met">
                        SLA Met
                      </MenuItem>,
                      <MenuItem key="breached" value="breached">
                        SLA Breached
                      </MenuItem>,
                    ]}
              </Select>
            </FormControl>
          </Grid>
          <Grid size={{ xs: 12, sm: 6, md: 4 }}>
            <FormControl fullWidth size="small">
              <InputLabel>Ticket Status</InputLabel>
              <Select
                name="status"
                value={filters.status}
                label="Ticket Status"
                onChange={handleFilterChange}
              >
                <MenuItem value="">All Statuses</MenuItem>
                {STATUS_OPTIONS.map((status) => (
                  <MenuItem key={status} value={status}>
                    {status}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid size={{ xs: 12, sm: 6, md: 4 }}>
            <TextField
              fullWidth
              size="small"
              type="date"
              name="start_date"
              label="Created from"
              value={filters.start_date}
              onChange={handleFilterChange}
              InputLabelProps={{ shrink: true }}
            />
          </Grid>
          <Grid size={{ xs: 12, sm: 6, md: 4 }}>
            <TextField
              fullWidth
              size="small"
              type="date"
              name="end_date"
              label="Created to"
              value={filters.end_date}
              onChange={handleFilterChange}
              InputLabelProps={{ shrink: true }}
            />
          </Grid>
        </Grid>
        <Box
          sx={{ display: "flex", gap: 1, justifyContent: "flex-end", mt: 2 }}
        >
          <Button variant="outlined" onClick={handleReset}>
            Reset
          </Button>
          <Button
            variant="contained"
            onClick={fetchTrends}
            disabled={loading}
            sx={{ bgcolor: "#43B02A", "&:hover": { bgcolor: "#3a9624" } }}
          >
            {loading ? <CircularProgress size={22} color="inherit" /> : "Apply"}
          </Button>
        </Box>
      </Paper>

      {usedFallback && !error && (
        <Alert severity="info" sx={{ mb: 2 }}>
          Trends API unavailable — showing aggregated data from ticket list.
        </Alert>
      )}
      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      {loading ? (
        <Box sx={{ display: "flex", justifyContent: "center", py: 6 }}>
          <CircularProgress />
        </Box>
      ) : (
        <>
          <Grid container spacing={2} sx={{ mb: 3 }}>
            <Grid size={{ xs: 12, sm: 6, md: 3 }}>
              <SummaryCard
                label="Total Tickets"
                value={summary.ticket_count ?? 0}
                color="#ff6b35"
              />
            </Grid>
            <Grid size={{ xs: 12, sm: 6, md: 3 }}>
              <SummaryCard
                label="Resolved / Closed"
                value={summary.resolved_count ?? 0}
                color="#4caf50"
              />
            </Grid>
            <Grid size={{ xs: 12, sm: 6, md: 3 }}>
              <SummaryCard
                label="Avg Resolution"
                value={formatResolutionHours(summary.avg_resolution_hours)}
                color="#ffc107"
              />
            </Grid>
            <Grid size={{ xs: 12, sm: 6, md: 3 }}>
              <SummaryCard
                label="SLA Breached"
                value={summary.breached_sla_count ?? 0}
                color="#f44336"
              />
            </Grid>
          </Grid>
        </>
      )}
    </Box>
  );
};

export default TrendsAnalysisTab;
